namespace fs=std::filesystem;
std::size_t checks=0;
void require(bool pass,const std::string& why){++checks;if(!pass)throw std::runtime_error(why);}
std::string read(const fs::path& p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("cannot read fixture "+p.string());return {std::istreambuf_iterator<char>(f),{}};}
void equal(const std::string& a,const std::string& b,const std::string& why){++checks;if(a!=b){std::size_t i=0;while(i<a.size()&&i<b.size()&&a[i]==b[i])++i;throw std::runtime_error(why+" differs at byte "+std::to_string(i)+"\nactual: "+a.substr(i,300)+"\nexpect: "+b.substr(i,300));}}
bool has(const std::vector<std::string>& lines,const std::string& s){return std::any_of(lines.begin(),lines.end(),[&](const auto& l){return l.find(s)!=l.npos;});}
template<class F>void rejects(F fn,const std::string& why){bool threw=false;try{fn();}catch(const std::exception&){threw=true;}require(threw,why);}
const SexprList& ls(const Sexpr& n){return std::get<SexprList>(n.v);}
std::string atom(const Sexpr& n){if(auto p=std::get_if<std::string>(&n.v))return *p;if(auto p=std::get_if<Sexpr::Sym>(&n.v))return p->name;return sexpr_fmt_num(std::get<double>(n.v));}
bool tag(const Sexpr& n,const std::string& s){auto p=std::get_if<SexprList>(&n.v);return p&&!p->empty()&&atom(p->front())==s;}
const Sexpr* sub(const Sexpr& n,const std::string& s){for(const auto& c:ls(n))if(tag(c,s))return &c;return nullptr;}
Sexpr* mut_sub(Sexpr& n,const std::string& s){for(auto& c:std::get<SexprList>(n.v))if(tag(c,s))return &c;return nullptr;}
double num(const Sexpr& n,std::size_t i){return std::get<double>(ls(n).at(i).v);}
std::string prop(const Sexpr& fp,const std::string& key){for(const auto& c:ls(fp))if(tag(c,"property")&&atom(ls(c).at(1))==key)return atom(ls(c).at(2));return {};}
const JsonNode& field(const JsonNode& n,const std::string& k){auto p=object_field(n,k);if(!p)throw std::runtime_error("fixture field missing "+k);return *p;}
PcbCheckFootprintPtr small(){return pcb_check_footprint("fixture.kicad_mod",R"((footprint "fixture" (fp_rect (start -1 -1) (end 1 1) (layer "F.CrtYd")) (pad "1" smd rect (at -0.5 0) (size 0.3 0.6)) (pad "2" smd rect (at 0.5 0) (size 0.3 0.6))))");}
PcbCheckInstance part(std::string ref,double x,double y,int pins,std::string sheet="s"){PcbCheckInstance i;i.ref=ref;i.x=x;i.y=y;i.sheet=sheet;i.mod=small();for(int n=1;n<=pins;++n)i.pad_nets[std::to_string(n)]={n,"N"+std::to_string(n)};return i;}
